/**
 * Vercel Serverless Function — proxy download counts.
 *
 * Route: GET /api/downloads
 * Caches at Vercel Edge for 5 minutes (s-maxage=300).
 *
 * Data source priority:
 *   1. Same-site /data/release.json (generated by CI with a token; works for
 *      Pre-release tags, which the anonymous GitHub "list releases" endpoint
 *      does NOT return — that endpoint returns an empty array for this repo,
 *      which previously caused a permanent 404).
 *   2. GitHub `GET /releases/tags/{tag}` for live download counts (anonymous
 *      access to a specific published tag works even for prereleases).
 *   3. Static fallback: the download counts already recorded in release.json.
 * Plus POST /api/beacon site-guided click counts (GitCode has no download
 * counters in its v5 API) — merged into total_downloads only when enabled.
 *
 * Security: repo / tag are never user-controlled; no SSRF surface.
 */

const REPO = 'citrusli2026/dsh-electron-shell'
const SITE_ORIGIN = process.env.SITE_ORIGIN || 'https://dsh-desktop.com'
const CACHE_MAX_AGE = 300
const GH_HEADERS = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'dsh-desktop-download-proxy',
}

function classifyAsset(name) {
  if (/^dsh-desktop-.+\.(dmg|exe|deb)$/.test(name)) return 'installer'
  if (/^dsh-desktop-.+\.(dmg|exe|deb)\.sha256$/.test(name)) return 'checksum'
  return null
}

async function fetchLocalReleaseData() {
  // Always read the same-site manifest from a fixed origin. Never trust the
  // incoming Host / X-Forwarded-Host header: that would let a caller point the
  // function at an arbitrary URL and turn this into an SSRF vector.
  const res = await fetch(`${SITE_ORIGIN}/data/release.json`, {
    headers: { Accept: 'application/json' },
  })
  if (!res.ok) return null
  const payload = await res.json()
  const rel = payload && payload.release
  if (!rel || typeof rel.tag !== 'string' || !Array.isArray(rel.assets)) return null
  return {
    tag: rel.tag,
    generated_at: typeof payload.generated_at === 'string' ? payload.generated_at : new Date().toISOString(),
    stats: payload.stats,
    assets: rel.assets.filter(a => classifyAsset(a.name) !== null),
  }
}

async function fetchLiveDownloads(tag) {
  const res = await fetch(`https://api.github.com/repos/${REPO}/releases/tags/${encodeURIComponent(tag)}`, {
    headers: GH_HEADERS,
  })
  if (!res.ok) return null
  const release = await res.json()
  if (!release || !Array.isArray(release.assets)) return null
  const byName = new Map(release.assets.map(a => [a.name, a.download_count || 0]))
  return byName
}

async function fetchLiveTotalDownloads() {
  // 全版本累计安装包下载（按平台分别）。最新 release 的计数随每个新版本
  // 归零，累计值才反映真实使用量；per_page=100 一次拿全（本仓库约 15 个
  // release）。
  const res = await fetch(`https://api.github.com/repos/${REPO}/releases?per_page=100`, {
    headers: GH_HEADERS,
  })
  if (!res.ok) return null
  const releases = await res.json()
  if (!Array.isArray(releases)) return null
  let mac = 0
  let win = 0
  let linux = 0
  let count = 0
  for (const r of releases) {
    if (r.draft || !Array.isArray(r.assets)) continue
    count += 1
    for (const a of r.assets) {
      if (classifyAsset(a.name) !== 'installer') continue
      if (a.name.endsWith('.dmg')) mac += a.download_count || 0
      else if (a.name.endsWith('.exe')) win += a.download_count || 0
      else linux += a.download_count || 0
    }
  }
  return { mac, win, linux, releases: count }
}

async function fetchGuidedCounts() {
  // Official-site download-link guidance (clicks) per source/platform,
  // recorded by POST /api/beacon. Enabled only when Upstash envs exist;
  // GitHub counts remain real CDN downloads from the API above.
  const url = process.env.UPSTASH_REDIS_REST_URL
  const token = process.env.UPSTASH_REDIS_REST_TOKEN
  if (!url || !token) return null
  const keys = ['dl:github:mac', 'dl:github:win', 'dl:github:linux', 'dl:gitcode:mac', 'dl:gitcode:win', 'dl:gitcode:linux']
  try {
    const res = await fetch(`${url}/mget`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ keys }),
    })
    if (!res.ok) return null
    const values = await res.json()
    if (!Array.isArray(values)) return null
    const get = (i) => Number(values[i]?.result?.[0]) || 0
    return {
      github: get(0) + get(1) + get(2),
      gitcode: get(3) + get(4) + get(5),
    }
  } catch (_) {
    return null
  }
}

async function fetchLegacyGitHubList() {
  // Fallback for stable (non-prerelease) publishes where the anonymous
  // list endpoint is reliable.
  const res = await fetch(`https://api.github.com/repos/${REPO}/releases?per_page=5`, {
    headers: GH_HEADERS,
  })
  if (!res.ok) return null
  const releases = await res.json()
  if (!Array.isArray(releases)) return null
  const latest = releases.find(r => !r.draft)
  if (!latest) return null
  return {
    tag: latest.tag_name,
    generated_at: new Date().toISOString(),
    assets: latest.assets
      .filter(a => classifyAsset(a.name) !== null)
      .map(a => ({ name: a.name, downloads: a.download_count || 0, kind: classifyAsset(a.name) })),
  }
}

module.exports = async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*')
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS')
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type')

  if (req.method === 'OPTIONS') {
    res.status(200).end()
    return
  }
  if (req.method !== 'GET') {
    res.status(405).json({ error: 'Method not allowed' })
    return
  }

  try {
    // 1) Same-site release manifest — authoritative for "a release exists".
    const local = await fetchLocalReleaseData()
    if (!local) {
      // 2) Legacy path — anonymous list endpoint (stable releases only).
      const legacy = await fetchLegacyGitHubList()
      if (legacy) {
        res.setHeader('Cache-Control', `public, s-maxage=${CACHE_MAX_AGE}, stale-while-revalidate=600`)
        res.setHeader('Content-Type', 'application/json')
        res.status(200).json({ ...legacy, source: 'github' })
        return
      }
      res.status(404).json({ error: 'No published release found' })
      return
    }

    // 3) Live download counts from the specific published tag (works for
    //    prereleases), else the counts baked into release.json.
    let downloadsByAsset = null
    let liveTotal = null
    try {
      downloadsByAsset = await fetchLiveDownloads(local.tag)
    } catch (_) {
      downloadsByAsset = null
    }
    try {
      liveTotal = await fetchLiveTotalDownloads()
    } catch (_) {
      liveTotal = null
    }

    const assets = local.assets.map(a => ({
      name: a.name,
      downloads:
        (downloadsByAsset && downloadsByAsset.has(a.name))
          ? downloadsByAsset.get(a.name)
          : (typeof a.downloads === 'number' ? a.downloads : 0),
      kind: classifyAsset(a.name),
    }))

    res.setHeader('Cache-Control', `public, s-maxage=${CACHE_MAX_AGE}, stale-while-revalidate=600`)
    res.setHeader('Content-Type', 'application/json')
    const ghTotal =
      (liveTotal && liveTotal.mac + liveTotal.win + liveTotal.linux) ||
      (typeof local.stats?.installer_downloads === 'number' ? local.stats.installer_downloads : null)
    const guided = await fetchGuidedCounts()
    res.status(200).json({
      tag: local.tag,
      generated_at: downloadsByAsset ? new Date().toISOString() : local.generated_at,
      source: downloadsByAsset ? 'github' : 'release-data',
      total_downloads: ghTotal !== null && guided ? ghTotal + guided.github + guided.gitcode : ghTotal,
      github_downloads: ghTotal,
      gitcode_downloads: guided ? guided.github + guided.gitcode : null,
      gitcode_guided_downloads: guided?.gitcode ?? null,
      mac_downloads:
        (liveTotal && liveTotal.mac) ||
        (typeof local.stats?.mac_downloads === 'number' ? local.stats.mac_downloads : null),
      win_downloads:
        (liveTotal && liveTotal.win) ||
        (typeof local.stats?.win_downloads === 'number' ? local.stats.win_downloads : null),
      linux_downloads:
        (liveTotal && liveTotal.linux) ||
        (typeof local.stats?.linux_downloads === 'number' ? local.stats.linux_downloads : null),
      released_versions: (liveTotal && liveTotal.releases) || local.stats?.releases || null,
      assets,
    })
  } catch (err) {
    res.status(500).json({ error: 'Internal error' })
  }
}
